:root {
  --tirc-border: #01524F;
  --tirc-text: #01524F;

  --tirc-fill-light: #EDF7F5;
  --tirc-fill-middle: #D3E8E2;
  --tirc-fill-base: #BDDBD4;

  --tirc-diameter: 100vmin;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  border: none;
  background: transparent !important;

  /* El fondo del documento no actúa como botón. */
  pointer-events: none;
}

.tirc-widget,
.tirc-widget * {
  box-sizing: border-box;
}

.tirc-widget {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: transparent;
  pointer-events: none;
}

.tirc-button {
  position: absolute;
  left: 50%;
  top: 50%;

  display: block;
  width: var(--tirc-diameter);
  height: var(--tirc-diameter);
  min-width: 0;
  min-height: 0;
  margin: 0;
  padding: 0;

  transform: translate(-50%, -50%);

  appearance: none;
  border: none;
  border-radius: 50%;
  background: transparent;

  /* Recorta tanto el dibujo como su área interactiva interna. */
  clip-path: circle(50% at 50% 50%);
  overflow: hidden;
  pointer-events: auto;

  cursor: pointer;
  user-select: none;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}

/* Acabado interior: no necesita márgenes para una sombra exterior. */
.tirc-button::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  pointer-events: none;

  box-shadow:
    inset 0 -3px 5px rgba(1, 82, 79, 0.14);

  transition: box-shadow 120ms ease;
}

.tirc-svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: transparent;
  shape-rendering: geometricPrecision;
  pointer-events: none;
}

.tirc-fill-light {
  stop-color: var(--tirc-fill-light);
}

.tirc-fill-middle {
  stop-color: var(--tirc-fill-middle);
}

.tirc-fill-base {
  stop-color: var(--tirc-fill-base);
}

.tirc-fill-light,
.tirc-fill-middle,
.tirc-fill-base {
  transition: stop-color 120ms ease;
}

.tirc-circle {
  fill: url("#tirc-surface");
  stroke: var(--tirc-border);
  stroke-width: 7;
}

.tirc-highlight {
  fill: none;
  stroke: #FFFFFF;
  stroke-width: 3;
  stroke-linecap: round;
  opacity: 0.65;
  transition: opacity 120ms ease;
}

.tirc-content {
  transform-box: view-box;
  transform-origin: 50% 50%;
  transform: scale(1);
}

.tirc-title,
.tirc-identifier {
  fill: var(--tirc-text);

  font-family:
    "Bahnschrift",
    "DIN Alternate",
    Consolas,
    "Liberation Mono",
    monospace;

  font-style: normal;
  font-variant-numeric: tabular-nums;
  font-variant-ligatures: none;

  text-anchor: middle;
  dominant-baseline: central;
}

.tirc-title {
  font-size: 56px;
  font-weight: 600;
  letter-spacing: 1px;
}

.tirc-identifier {
  font-size: 50px;
  font-weight: 600;
  letter-spacing: 0;
}

@media (hover: hover) {
  .tirc-button:hover {
    --tirc-fill-light: #F5FCFA;
    --tirc-fill-middle: #DDEFE9;
    --tirc-fill-base: #C8E3DB;
  }

  .tirc-button:hover .tirc-highlight {
    opacity: 0.85;
  }
}

/* Hundimiento centrado sin reducir el contorno interactivo. */
.tirc-button:active {
  --tirc-fill-light: #D5E8E2;
  --tirc-fill-middle: #C9E1D9;
  --tirc-fill-base: #B9D8CE;
}

.tirc-button:active::after {
  box-shadow:
    inset 0 3px 7px rgba(1, 82, 79, 0.28),
    inset 0 -1px 2px rgba(255, 255, 255, 0.40);
}

.tirc-button:active .tirc-content {
  transform: scale(0.98);
}

.tirc-button:active .tirc-highlight {
  opacity: 0.25;
}

.tirc-button:focus-visible {
  outline: 2px solid #FFFFFF;
  outline-offset: -6px;
}

@media (prefers-reduced-motion: reduce) {
  .tirc-button::after,
  .tirc-fill-light,
  .tirc-fill-middle,
  .tirc-fill-base,
  .tirc-highlight {
    transition: none;
  }
}

