"use strict";

(function () {
  const DEFAULT_TITLE = "TIRC";
  const DEFAULT_IDENTIFIER = "06-2A";
  const TEXT_CENTER = 124;
  const BASE_IDENTIFIER_SIZE = 50;
  const MAX_IDENTIFIER_WIDTH = 194;

  let container = null;
  let button = null;
  let labels = null;
  let titleElement = null;
  let identifierElement = null;

  let latestWidget = null;
  let resizeObserver = null;

  function centerText() {
    if (!labels || !titleElement || !identifierElement) {
      return;
    }

    labels.removeAttribute("transform");

    titleElement.setAttribute("x", String(TEXT_CENTER));
    identifierElement.setAttribute("x", String(TEXT_CENTER));

    identifierElement.style.fontSize =
      BASE_IDENTIFIER_SIZE + "px";

    const textWidth = identifierElement.getComputedTextLength();

    if (textWidth > MAX_IDENTIFIER_WIDTH) {
      identifierElement.style.fontSize =
        (
          BASE_IDENTIFIER_SIZE *
          MAX_IDENTIFIER_WIDTH /
          textWidth
        ) + "px";
    }

    // Centrado horizontal de cada línea.
    [titleElement, identifierElement].forEach(function (element) {
      const bounds = element.getBBox();

      if (bounds.width <= 0) return;

      const currentCenter = bounds.x + bounds.width / 2;

      element.setAttribute(
        "x",
        String(TEXT_CENTER + TEXT_CENTER - currentCenter)
      );
    });

    // Centrado vertical del conjunto.
    const blockBounds = labels.getBBox();

    if (blockBounds.height <= 0) return;

    const offsetY =
      TEXT_CENTER -
      (blockBounds.y + blockBounds.height / 2);

    labels.setAttribute(
      "transform",
      "translate(0 " + offsetY + ")"
    );
  }

  function resizeLayout() {
    if (!container) return;

    const width = container.clientWidth;
    const height = container.clientHeight;

    if (width <= 0 || height <= 0) return;

    /*
     * Mantiene un círculo perfecto.
     * Si ancho y alto son iguales, ocupa todo el widget.
     */
    const diameter = Math.min(width, height);

    container.style.setProperty(
      "--tirc-diameter",
      diameter + "px"
    );

    centerText();
  }

  function render(w) {
    if (!titleElement || !identifierElement || !button) {
      return;
    }

    const name =
      w && typeof w.name === "string"
        ? w.name.trim()
        : "";

    /*
     * Formato del campo NOMBRE:
     *
     * FIRC | 06-2A
     *
     * Antes de "|"  → texto superior.
     * Después de "|" → texto inferior.
     *
     * Sin separador se conserva el comportamiento anterior.
     */
    const separatorPosition = name.indexOf("|");

    let title = DEFAULT_TITLE;
    let identifier = DEFAULT_IDENTIFIER;

    if (separatorPosition >= 0) {
      title =
        name.slice(0, separatorPosition).trim() ||
        DEFAULT_TITLE;

      identifier =
        name.slice(separatorPosition + 1).trim() ||
        DEFAULT_IDENTIFIER;
    } else {
      identifier = name || DEFAULT_IDENTIFIER;
    }

    titleElement.textContent = title;
    identifierElement.textContent = identifier;

    button.setAttribute(
      "aria-label",
      title + " " + identifier
    );

    centerText();
  }

  window.onWidgetUpdate = function (w) {
    latestWidget = w;
    render(w);
  };

  function initialize() {
    container = document.querySelector(".tirc-widget");
    button = document.querySelector(".tirc-button");
    labels = document.querySelector(".tirc-labels");
    titleElement = document.querySelector(".tirc-title");
    identifierElement = document.querySelector(".tirc-identifier");

    if (
      !container ||
      !button ||
      !labels ||
      !titleElement ||
      !identifierElement
    ) {
      return;
    }

    render(latestWidget || window.WIDGET || null);
    resizeLayout();

    requestAnimationFrame(centerText);

    if (document.fonts && document.fonts.ready) {
      document.fonts.ready.then(centerText);
    }

    if (typeof ResizeObserver !== "undefined") {
      resizeObserver = new ResizeObserver(resizeLayout);
      resizeObserver.observe(container);
    } else {
      window.addEventListener("resize", resizeLayout);
    }

    /*
     * Sin variables del PLC ni acción de clic configurada.
     * El recorte circular se aplica dentro del widget.
     * No modifica el contenedor externo de PsiCore.
     */
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      initialize,
      { once: true }
    );
  } else {
    initialize();
  }
})();
